mat2 rot90 = mat2(0.0, 1.0, -1.0, 0.0); // column major!

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    // scale so that the initial tile (which will be the whole patch) 
    // is centred and covers at least the whole display.
    // The initial tile is horizontal, so the range is [0,1]x[0,0.5]
    float scale = max(iResolution.x, 2.0 * iResolution.y);
    vec2 p = (fragCoord + vec2(scale - iResolution.x, scale - 2.0 * iResolution.y) * 0.5) / scale;

    //st_assert(p.x >= 0.0 && p.x <= 1.0, 0);
    //st_assert(p.y >= 0.0 && p.y <= 0.5, 1);

    // We keeps track of parity of 90 degree rotations.
    // 0 is a horizontal tile.
    // See https://tilings.math.uni-bielefeld.de/substitution/domino/
    int count_rots = 0; 

    #define ROUNDS 5
    for (int round = 0; round < ROUNDS; ++round) {

        //st_assert(p.x >= -0.01 && p.x <= 1.01, 0);
        //st_assert(p.y >= 0.0 && p.y <= 0.5, 1);

        if (p.x <= 0.25) {
            p = rot90 * (p + vec2(0.0, -0.5)) * 2.0;
            count_rots += 1;
        } else if (p.x > 0.75) {
            p = rot90 * (p + vec2(-0.75, -0.5)) * 2.0;
            count_rots += 1;
        } else if (p.y <= 0.25) {
            p = (p - vec2(0.25, 0.0)) * 2.0;
        } else {
            p = (p - vec2(0.25, 0.25)) * 2.0;
        }
    }

    st_assert(p.x >= 0.0 && p.x <= 1.0, 0);
    st_assert(p.y >= 0.0 && p.y <= 0.5, 1);
    //fragColour = vec4(p.x, p.y, float(type), 1.0); return; // DEBUG

    vec2 pp = vec2(2.0, 4.0) * (p - vec2(0.5, 0.25));  // pp is in [-1,1] x [-1.0, 1.0]

    #define tau 6.283185307179586

    // uncomment the additional term to add some animation to the shapes
    float power = 0.75; // + (1.0 + sin(tau * fract(iTime / 10.0))) * 1.5;
    float d = pow(pow(abs(pp.x), power) + pow(abs(pp.y), power), 1.0/power);

    #define C0 vec4(0.2, 0.2, 0.4, 1.0) * 1.4 // dark blue
    #define C1 vec4(0.8, 0.7, 0.3, 1.0) // dark yellow
    #define C2 vec4(0.8, 0.2, 0.4, 1.0) // dark red
    #define WHITE vec4(1.0, 1.0, 1.0, 1.0)
    #define BLACK vec4(0.0, 0.0, 0.0, 1.0)

    vec4 base_colour = (count_rots % 3 == 0) ? C0 : 
                       (count_rots % 3 == 1) ? C1 : 
                       C2;
    vec4 colour = mix(base_colour / sqrt(length(pp)), BLACK, smoothstep(1.0, 1.01, d));

    fragColour = colour;

}
